-- 012_seed_advocacy_law.sql — بذر قانون المحاماة رقم 17 لسنة 1983 وتعديلاته
-- (231 مادة أصلية، منها 8 مواد ملغاة صراحةً فى النص المُوحَّد الرسمى).
--
-- المصدر: نسخة نصية استخرجها المستخدم بنفسه من موقع نقابة المحامين المصرية
-- (رابط PDF رسمى معتمد من النقابة نفسها https://egyls.com/قانون-المحاماة/،
-- بصيغة "وفقاً لآخر تعديل صادر فى 8 يوليو 2020" — نفس التاريخ المُتحقَّق منه
-- بشكل مستقل من آخر حاشية حكم دستورية فى المستند نفسه (جلسة 8/7/2020 بشأن
-- الفقرة الثانية من المادتين 34 و134) — تطابق مستقل يرفع الثقة فى صحة النسخة.
--
-- منهجية الاستخراج: pdfplumber + خوارزمية تصحيح اتجاه RTL على مستوى "الشرائح"
-- (character-class runs) وليس على مستوى السطر الكامل أو الكلمة فقط — إصلاح
-- جذرى لعطل حرج اكتُشف أثناء هذا الاستخراج تحديداً: الإصلاح الأول (عكس السطر
-- كاملاً، كما استُخدم فى migrations/009) يُفسد ترتيب أرقام المواد والسنوات
-- multi-digit عند التصاقها بكلمة عربية بلا مسافة (مثال: "لسنة1983" كانت
-- تتحوّل خطأً إلى "3891"). التحقق: كل رقم مادة وكل تاريخ حاسم فى هذا الملف
-- (رقم/سنة القانون، تاريخ آخر تعديل 8 يوليو 2020، تواريخ كل حكم دستورية
-- مُستخدَم لتحديد حالة مادة) قُورن يدوياً بنص pdfplumber الخام (غير المُعالَج)
-- صفحة بصفحة قبل اعتماده.
--
-- ⚠️ حالة كل مادة (سارية/ملغاة) لم تُخمَّن من الحواشى الـ25 المرفقة فى نهاية
-- المستند — استُخرجت مباشرة من نص متن كل مادة نفسه: النسخة الرسمية المُوحَّدة
-- تضع كلمة "ملغاة" أو "قُضى بعدم دستورية المادة" أو "قُضى بسقوط المادة" كمتن
-- كامل للمادة الملغاة (بدل حذفها من الترقيم) — هذا أدق من تفسير الحواشى يدوياً
-- لأنه يعكس ما تُقرّه الجهة الرسمية نفسها كنص "معتمد حالياً"، ويتفادى فخّاً
-- حقيقياً وُجد أثناء المراجعة: بعض أرقام المواد (مثل 30، 153، 216) أُلغيت
-- تاريخياً بقانون قديم ثم — حسب هذا المنطق نفسه — ظلت تُعرَض بنص "ملغاة" فى
-- النسخة الحالية بدل إعادة استخدام الرقم لمادة جديدة مختلفة، ما كان سيُضلِّل
-- أى استنتاج مبنى على الحواشى وحدها دون فحص متن كل مادة فعلياً.
--
-- المواد الملغاة الثمانى (بحالة article_versions.status='repealed'، والمتن كما
-- يظهر رسمياً "ملغاة/قُضى بعدم دستورية/قُضى بسقوط" لكل منها): 2، 3، 5, 15،
-- 30، 84، 153، 216.
--
-- ⚠️ استثناء واحد صريح غير محسوم: المادة 85 — حاشيتها الرسمية (رقم 13) تنص
-- "قُضى بسقوط المادة (85)" بإطلاق (بلا تقييد بفقرة معينة)، لكن متن المادة فى
-- المصدر نفسه يتضمن فقرة موضوعية كاملة بعد إشارة السقوط مباشرة. تعارض حقيقى
-- بين إطلاق نص الحاشية ووجود نص متبقٍ فعلى — لم أحسمه بالتخمين فى أى الاتجاهين؛
-- أُبقيت المادة سارية احترازاً (القاعدة الأكثر أماناً: لا تُخفِ نصاً قد يكون
-- صحيحاً)، مع توثيق كامل للتعارض فى article_versions.change_note، وتوصية
-- صريحة للمستخدم بمراجعة قانونية مباشرة لهذه المادة تحديداً.
--
-- ⚠️ نطاق متعمَّد غير مكتمل (ليس نقصاً صامتاً): 7 مواد "مكرّرة" (13 مكرراً،
-- 46 مكرراً، 50 مكرراً، 135 مكرراً، 156 مكرراً، 156 مكرراً(1)، 206 مكرراً)
-- استُبعِدت من هذه الدفعة عمداً. السبب الجذرى: عمود articles.article_no
-- عدد صحيح (integer) بقيد تفرّد UNIQUE(law_id, article_no)، والواجهة الأمامية
-- (CitationCard.tsx) تعرض هذا الرقم للمستخدم مباشرة بلا أى حقل بديل — أى ترميز
-- رقمى اصطناعى (مثل 13001 بدل "13 مكرراً") كان سيعرض للمستخدم رقم مادة خاطئ
-- فعلياً، وهو أسوأ من عدم إدخالها مؤقتاً. الحل الجذرى الصحيح (عمود نصى إضافى
-- article_suffix + تعديل مطابق فى الواجهة) يحتاج تغييراً بسيطاً فى مكانين
-- فقط (الكيان + مكوّن العرض)، ولم يُنفَّذ فى هذه الدفعة كى لا يُبطئ تسليم
-- الـ231 مادة الأساسية جاهزة ومُتحقَّقة الآن — موصى بمتابعته كدفعة صغيرة تالية.
--
-- 'legal_profession' فئة جديدة تُضاف صراحة لقيد laws.category ولـ DOMAIN_KEYS
-- (backend وfrontend معاً فى نفس هذه الدفعة) — نفس نمط 'insurance'/'aml_cft'
-- السابق، لتفادى فجوة النوع (type safety gap) المُوثَّقة مرتين من قبل.

BEGIN;

ALTER TABLE laws DROP CONSTRAINT IF EXISTS laws_category_check;
ALTER TABLE laws ADD CONSTRAINT laws_category_check
  CHECK (category IN ('labor','rent','personal_status','traffic','consumer_protection','insurance','aml_cft','legal_profession','other'));

INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at)
VALUES (
  17, 1983,
  $lt1$قانون رقم 17 لسنة 1983 بشأن إصدار قانون المحاماة$lt1$,
  $ls1$قانون المحاماة$ls1$,
  'legal_profession', 'amended',
  $lu1$https://egyls.com/%D9%82%D8%A7%D9%86%D9%88%D9%86-%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D9%85%D8%A7%D8%A9/$lu1$,
  '1983-03-31', '2020-07-08'
)
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;


