WITH ins_art_law17_11 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 11, $al11$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al11$, $ab11$تحفظ نسختان من الجداول المذكورة بالمادة السابقة بمقر النقابة العامة وتودع نسخة من هذه الجداول بمقر كل
محكمة من محاكم االستئناف ومحاكم القضاء االدارى ولدى النائب العام.
وتودع نسخة من جدول المحامين أمام محكمة النقض بمقرها وبمقر كل من المحكمة االدارية العليا والمحكمة
الدستورية العليا .
ويكون بكل نقابة فرعية جدوالن عامان وجداول ملحقة مقصورة على اثبات أسماء المحامين الذين توجد مقارهم
ف ي دائرتها .$ab11$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab11$تحفظ نسختان من الجداول المذكورة بالمادة السابقة بمقر النقابة العامة وتودع نسخة من هذه الجداول بمقر كل
محكمة من محاكم االستئناف ومحاكم القضاء االدارى ولدى النائب العام.
وتودع نسخة من جدول المحامين أمام محكمة النقض بمقرها وبمقر كل من المحكمة االدارية العليا والمحكمة
الدستورية العليا .
ويكون بكل نقابة فرعية جدوالن عامان وجداول ملحقة مقصورة على اثبات أسماء المحامين الذين توجد مقارهم
ف ي دائرتها .$ab11$, '1983-03-31', 'active', NULL FROM ins_art_law17_11;

