WITH ins_art_law17_13 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 13, $al13$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al13$, $ab13$يشترط فيمن يطلب قيد اسمه ف ي الجدول العام أن يكون:
١ - متمتعًا بالجنسية المصرية ومقي ًما بها إقامة دائمة وفقًا للضوابط الت ي يقررها مجلس النقابة، ويجوز لوزير
العدل وفقًا للقواعد الت ي يضعها بالتنسيق مع مجلس نقابة المحامين الترخيص للمحامين األجنبى بالعمل في دعوى
أو موضوع معين بشرط المعاملة بالمثل .
ويُنشى مجلس النقابة جداول خاصة بالمحامين األجانب والمحامين المشتغلين خارج جمهورية مصر العربية
وبقواعد التعامل من حيث تدرج القيد ورسومه واالشتراكات السنوية والخدمات الت ي تقدم لهذه الجداول. )٨ (
٢ - متمتعا باألهلية المدنية الكاملة.
٣ - أن يكون حاصالً على الثانوية العامة أو ما يعادلها من الشهادات األجنبية المعتمدة في مصر، وإجازة الحقوق
من إحدى كليات الحقوق أو شهادة من إحدى الجامعات األجنبية أو فروعها في مصر والت ي تعتبر معادلة لها طبقًا
ألحكام القوانين واللوائح المعمول بها في جمهورية مصر العربية. )٨ (
٤ - أال يكون قد سبق إدانته بحكم نهائى ف ي جنحة ماسة بالشرف أو األمانة أو بعقوبة جناية، ما لم يكن قد رد إليه
اعتباره .
٥ - أن يكون محمود السيرة، حسن السمعة، أهال لالحترام الواجب للمهنة، وأال تكون قد صدرت ضده أحكام
تأديبية أو انتهت عالقته بوظيفته أو مهنته أو انقطعت صلته بها ألسباب ماسة بصالحيته للوظيفة الت ي كان
يشغلها .
٦ - قضي بعدم دستورية البند السادس من الفقرة األولى )١٨(
٧ - أن يسدد رسوم القيد واالشتراك السنوى.
٨ - أال تقوم بشأنه حالة من حاالت عدم جواز الجمع الواردة ف ي المادة التالية.
ويجب الستمرار القيد ف ي الجداول توافر الشروط سالفة الذكر عدا البند رقم ٦ من هذه المادة، ويسقط القيد بقوة
القانون من تاريخ افتقاد أى من هذه الشروط دون حاجة إلى صدور قرار بذلك من لجنة القيد، ويجب اإلخطار
بهذا اإلجراء بكتاب موصى عليه، وإخطار النقابة الفرعية المختصة. )٥ ($ab13$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
