بهذا اإلجراء بكتاب موصى عليه، وإخطار النقابة الفرعية المختصة. )٥ ($ab13$, '1983-03-31', 'active', $an13$حكمت المحكمة الدستورية العليا (قضية 68 لسنة 18ق، جلسة 6/12/1999) بعدم دستورية البند السادس من الفقرة الأولى من هذه المادة.$an13$ FROM ins_art_law17_13;

WITH ins_art_law17_14 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 14, $al14$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al14$, $ab14$ال يجوز الجمع بين المحاماة واألعمال اآلتية :
١ - رئاسة مجلس النواب أو مجلس الشيوخ. )٨ (
٢ - منصب الوزارة.
٣ - الوظائف العامة ف ي الحكومة والهيئات العامة واالدارة المحلية. والوظائف ف ي شركات القطاع العام أو
الوظائف الخاصة، فيما عدا العمل باالدارة القانونية المصرح لها بذلك طبقا ألحكام هذا القانون، وفيما عدا أساتذة
القانون ف ي الجامعات المصرية ف ي الحاالت الت ي يجيزها هذا القانون.
وال تعد العضوية ف ي اللجان الحكومية العلمية أو المؤقتة أو القيام بمهام ذات صفة عرضية ال تستغرق أكثر من
ستة شهور أو الندب لتدريس القانون ف ي الجامعات والمعاهد العليا وظيفة يحظر معها الجمع بينها وبين المحاماة.
٤ - االشتغال بالتجارة .
٥ - شغل مركز رئيس مجلس االدارة أو العضو المنتدب أو عضو مجلس ادارة متفرغ ف ي شركات المساهمة أو
المدير ف ي الشركات ذات المسئولية المحدودة وشركات التضامن والتوصية .
٦ - المناصب الدينية .
وباستثناء ما ورد بالبند )٣(، يشترط التفرغ للمحاماة . )٦ ($ab14$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
