WITH ins_art_law17_17 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 17, $al17$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al17$, $ab17$تنعقد لجنة قبول المحامين مرة على األقل كل شهر، ويكون لها أمانة من بين موظفى النقابة يختار النقيب
أعضاءها، وتحرر محاضر بأعمالها يوقع عليها من رئيس اللجنة.
وال يصح انعقاد اللجنة اال بحضور ثالثة أعضاء على األقل، على أن يكون من بينهم النقيب أو وكيل النقابة .$ab17$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab17$تنعقد لجنة قبول المحامين مرة على األقل كل شهر، ويكون لها أمانة من بين موظفى النقابة يختار النقيب
أعضاءها، وتحرر محاضر بأعمالها يوقع عليها من رئيس اللجنة.
وال يصح انعقاد اللجنة اال بحضور ثالثة أعضاء على األقل، على أن يكون من بينهم النقيب أو وكيل النقابة .$ab17$, '1983-03-31', 'active', NULL FROM ins_art_law17_17;

WITH ins_art_law17_18 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 18, $al18$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al18$, $ab18$تصدر اللجنة قرارها بعد التحقق من توافر شروط القيد، وذلك خالل ثالثين يوما من تاريخ تقديم الطلب. واذا كان
قرارها برفض القيد تعين أن يكون مسببا ويخطر به طالب القيد خالل خمسة عشر يوما من تاريخ صدوره
بخطاب مسجل مصحوب بعلم الوصول .$ab18$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab18$تصدر اللجنة قرارها بعد التحقق من توافر شروط القيد، وذلك خالل ثالثين يوما من تاريخ تقديم الطلب. واذا كان
قرارها برفض القيد تعين أن يكون مسببا ويخطر به طالب القيد خالل خمسة عشر يوما من تاريخ صدوره
بخطاب مسجل مصحوب بعلم الوصول .$ab18$, '1983-03-31', 'active', NULL FROM ins_art_law17_18;

WITH ins_art_law17_19 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 19, $al19$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al19$, $ab19$لطالب القيد التظلم من القرار الصادر برفض قيده خالل خمسة عشر يوما من تاريخ اخطاره برفض طلبه. ويقدم
التظلم الى لجنة القبول الت ي تفصل ف ي التظلم بعد سماع أقواله.
ولطالب القيد إذا رفض تظلمه أو كانت قد انقضت مواعيد التظلم أن يطعن ف ي القرار الصادر برفض التظلم أو
رفض القيد أمام محكمة استئناف القاهرة خالل ثالثين يوما من تاريخ رفض التظلم أو من تاريخ انتهاء ميعاد
التظلم على حسب األحوال, ويكون لطالب القيد الطعن أمام ذات المحكمة إذا لم يفصل ف ي طلب قيده خالل المدة
المبينة بالمادة السابقة.
وال يجوز تجديد الطلب ف ي الحاالت المبينة بالفقرتين السابقتين اال إذا زالت األسباب المانعة من القيد .$ab19$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab19$لطالب القيد التظلم من القرار الصادر برفض قيده خالل خمسة عشر يوما من تاريخ اخطاره برفض طلبه. ويقدم
التظلم الى لجنة القبول الت ي تفصل ف ي التظلم بعد سماع أقواله.
ولطالب القيد إذا رفض تظلمه أو كانت قد انقضت مواعيد التظلم أن يطعن ف ي القرار الصادر برفض التظلم أو
رفض القيد أمام محكمة استئناف القاهرة خالل ثالثين يوما من تاريخ رفض التظلم أو من تاريخ انتهاء ميعاد
التظلم على حسب األحوال, ويكون لطالب القيد الطعن أمام ذات المحكمة إذا لم يفصل ف ي طلب قيده خالل المدة
المبينة بالمادة السابقة.
وال يجوز تجديد الطلب ف ي الحاالت المبينة بالفقرتين السابقتين اال إذا زالت األسباب المانعة من القيد .$ab19$, '1983-03-31', 'active', NULL FROM ins_art_law17_19;

WITH ins_art_law17_20 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 20, $al20$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al20$, $ab20$ال يجوز للمحام ي الذي يقيد اسمه بجدول المحاماة أن يزاول المهنة اال بعد حلف اليمين بالصيغه اآلتية:
)أقسم باهلل العظيم أن أمارس أعمال المحاماة بالشرف واألمانة واالستقالل وأن أحافظ على سر مهنة المحاماة
وتقاليدها وأن أحترم الدستور والقانون( .
ويكون حلف اليمين أمام لجنة قبول المحامين بحضور ثالثة من أعضائها على األقل وتثبت اجراءات حلف اليمين
ف ي محاضر اجتماعات اللجنة.
الفصل الثا لث
في القيد بجدول المحامين تحت التمري ن$ab20$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
