WITH ins_art_law17_22 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 22, $al22$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al22$, $ab22$يجب أن يلحق المحام ي تحت التمرين بمكتب أحد المحامين المقبولين للمرافعة أمام محاكم االستئناف أو محكمة
النقض، أو للعمل باحدى االدارات القانونية ف ي الجهات المرخص لها بذلك طبقا ألحكام هذا القانون تحت اشراف
أحد المحامين المقبولين أمام تلك المحاكم من العاملين باالدارة القانونية لهذه الجهة. واذا تعذر على المحام ي تحت
التمرين أن يجد مكتبا للتمرين فيه يتولى مجلس النقابة الفرعية الحاقه بأحد مكاتب المحامين .
وعلى طالب القيد أن يرفق بطلب قيده بجدول المحامين تحت التمرين بيانا باسم المحام ي الذي التحق بمكتبه
وعنوانه مرفقا به موافقة المحام ي، أو بيانا باالدارة القانونية بالجهة الت ي التحق بها والت ي يجوز للمحامين مزاولة
أعمال المحاماة فيها طبقا ألحكام هذا القانون واسم المحام ي الذي سيتولى االشراف عليه ف ي هذه االدارة مرفقا به
موافقتها .$ab22$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
