ستة أشهر من انقضاء المدة المشار إليها، ينتقل تلقائيًا إلى جدول غير المشتغلين دون حاجة إلى صدور قرار بذلك
من لجنة القيد، ويجوز له طلب إعادة القيد متى توافرت له الشروط المقررة في هذا القانون. )٨ ($ab24$, '1983-03-31', 'active', NULL FROM ins_art_law17_24;

WITH ins_art_law17_25 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 25, $al25$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al25$, $ab25$يكون تمرين المحام ي ف ي السنة األولى بأن يعاون المحام ي الذي يتمرن بمكتبه أو باالدارة القانونية الت ي ألحق بها،
ف ي اعداد األبحاث والمراجع واستخالص أحكام المحاكم وتحضير صحف الدعاوى ومستنداتها .
ويجوز له الحضور أمام المحاكم الجزئية باسم المحام ي الذي يتمرن بمكتبه أو عن محامى االدارة القانونية الت ي
ألحق بها دون أن يكون له الحق ف ي أن يوقع صحف الدعاوى أو المذكرات أو األوراق الت ي تقدم الى المحاكم
المذكورة أو الى مكاتب الشهر والتوثيق أو مكاتب السجل التجارى أو أن يعد عقودا باسمه.$ab25$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab25$يكون تمرين المحام ي ف ي السنة األولى بأن يعاون المحام ي الذي يتمرن بمكتبه أو باالدارة القانونية الت ي ألحق بها،
ف ي اعداد األبحاث والمراجع واستخالص أحكام المحاكم وتحضير صحف الدعاوى ومستنداتها .
ويجوز له الحضور أمام المحاكم الجزئية باسم المحام ي الذي يتمرن بمكتبه أو عن محامى االدارة القانونية الت ي
ألحق بها دون أن يكون له الحق ف ي أن يوقع صحف الدعاوى أو المذكرات أو األوراق الت ي تقدم الى المحاكم
المذكورة أو الى مكاتب الشهر والتوثيق أو مكاتب السجل التجارى أو أن يعد عقودا باسمه.$ab25$, '1983-03-31', 'active', NULL FROM ins_art_law17_25;

WITH ins_art_law17_26 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 26, $al26$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في جدول المحامي ن$al26$, $ab26$للمحام ي تحت التمرين ف ي السنة الثانية أن يترافع باسم ه أمام المحاكم الجزئية - فيما عدا محاكم أمن الدولة
والمحاكم المستعجله - وذلك تحت اشراف المحام ي الذي التحق بمكتبه أو محامى االدارة القانونية الت ي ألحق بها .
كما يجوز له الحضور باسمه ف ي تحقيقات النيابه والشرطة ف ي مواد المحاكمات والجنح وباسم المحام ي الذ ي
يتمرن ف ي مكتبه ف ي الجنايات.
ويجوز له الحضور أمام المحاكم االبتدائية عن المحام ي الذي يتمرن ف ي مكتبه أو محامى االدارة القانونية الت ي
ألحق بها .
كما يجوز له الحضور أمام هذه المحاكم عن محام آخر البداء طلب التأجيل .
كما يجوز له أن يعد باسمه العقود الت ي ال تجاوز قيمتها خمسة آالف جنيه والت ي ال تحتاج الى شهر أو توثيق .
وفى جميع األحوال ال يجوز للمحام ي تحت التمرين تقديم فتوى كتابية باسمه أو التوقيع على العقود الت ي تقدم الى
الشهر العقارى فيما عدا طلبات اثبات التاريخ .$ab26$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
