WITH ins_art_law17_31 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 31, $al31$الباب األول — في القيد بجدول المحامي ن — الفصل الرابع — في القبول للمرافعة أمام المحاكم االبتدائي ة$al31$, $ab31$يشترط لقيد المحام ي ف ي جدول المحامين أمام المحاكم االبتدائية:
)١( أن يكون قد أمضى دون انقطاع فترة التمرين المنصوص عليها ف ي المادة )٢٤( .
)٢( أن يقدم صورة من البطاقة الضريبية سارية المفعول ثابت بها اشتغاله بالمحاماة دون سواها .
)٣( أن يجتاز بنجاح اختبارات معهد المحاماة .
ويسرى هذا الشرط على المحامين الذين يبدأ قيدهم بعد تاريخ العمل بهذا القانون وبعد صدور قرار مجلس النقابة
العامة ف ي تنظيم االلتحاق بمعهد المحاماة أو معاهد الدراسات القانونية المنصوص عليها ف ي المادة )٢٨(. )٥ ($ab31$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
