WITH ins_art_law17_33 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 33, $al33$الباب األول — في القيد بجدول المحامي ن — الفصل الرابع — في القبول للمرافعة أمام المحاكم االبتدائي ة$al33$, $ab33$يقدم طلب القيد ف ي جدول المحامين أمام المحاكم االبتدائية الى لجنة قبول المحامين المنصوص عليها ف ي المادة
)١٦( .
ولمجلس النقابة أن يشكل لجنة خاصة للقبول أمام المحاكم االبتدائية من خمسة من بين أعضائها يرأسها أقدمهم،
وتسريعليها األحكام المقررة بالنسبة للجنة قبول المحامين.
وتقدم طلبات القيد الى لجنة القبول المختصة مصحوبة بالمستندات المثبتة لتوافر شروط القيد وشهادة من النقابة
الفرعية الت ي يقع ف ي دائرتها مكتب المحام ي أو االدارة القانونية الت ي قضى فيها فترة التمرين وذلك طبقا لما يقرره
النظام الداخل ي للنقابة.
وتبلغ قرارات اللجنة بالقبول أو الرفض الى الطالب والى النقابة الفرعية المختصة خالل خمسة عشر يوما
بخطاب مسجل مصحوب بعلم الوصول .
ولمن رفض طلبه أن يطعن ف ي قرار الرفض أمام محكمة استئناف القاهرة خالل ستين يوما من تاريخ ابالغه
بالقرار.$ab33$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
