WITH ins_art_law17_34 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 34, $al34$الباب األول — في القيد بجدول المحامي ن — الفصل الرابع — في القبول للمرافعة أمام المحاكم االبتدائي ة$al34$, $ab34$يجوز للمحام ي المقيد أمام المحاكم االبتدائية أن يفتح مكتب باسمه منفردا أو مع غيره، ويكون حضوره أمام
المحاكم الجزئية والمحاكم االبتدائية والمحاكم االدارية الت ي تناظرها ويجوز له الحضور أمام محاكم االستئناف
ومحاكم القضاء االدارى نيابة عن أحد المحامين المقيدين أمام هذه المحاكم وعلى مسئوليته كما يكون له أن
يحضر باسمه ف ي سائر التحقيقات الت ي تجريها النيابة العامة.
وللمحامى المقيد أمام المحاكم االبتدائية اعداد العقود المختلفة وشهرها وتوق يع الطلبات واألوراق المتعلقة بها،
وذلك فيما عدا عقود تأسيس شركات المساهمة وعقود الرهن الرسمى أو تعديلها .
وال يجوز للمحام ي أمام المحاكم االبتدائية اعطاء اآلراء والفتاوى القانونية المكتوبة.$ab34$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab34$يجوز للمحام ي المقيد أمام المحاكم االبتدائية أن يفتح مكتب باسمه منفردا أو مع غيره، ويكون حضوره أمام
