يحضر باسمه ف ي سائر التحقيقات الت ي تجريها النيابة العامة.
وللمحامى المقيد أمام المحاكم االبتدائية اعداد العقود المختلفة وشهرها وتوق يع الطلبات واألوراق المتعلقة بها،
