WITH ins_art_law17_35 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 35, $al35$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — في القبول للمرافعة أمام محاكم االستئن ا ف$al35$, $ab35$يشترط لقيد المحام ي أمام محاكم االستئناف أن يكون المحام ي قد اشتغل بالمحاماة فعال خمس سنوات على األقل
من تاريخ قيد اسمه بجدول المحامين المقبولين للمرافعة أمام المحاكم االبتدائية.
ويثبت االشتغال بالمحاماة بت قديم بيان رسمى بالجلسات الت ي يكون قد حضرها وبتقديم صور المذكرات واألوراق
القضائية الت ي يكون قد باشرها أو الفتاوى واآلراء القانونية أو العقود الت ي يكون قد أعدها وأن يقدم شهادة من
النقابة الفرعية الت ي يزاول عمله ف ي دائرتها وذلك طبقا لما يقرره النظام الداخل ي للنقابة.
ويجوز استثناء القيد مباشرة أمام محاكم االستئناف لمن لم يسبق قيده أمام المحاكم االبتدائية إذا كان قد اشتغل
بأعمال تعد نظيرة ألعمال المحاماة طبقا ألحكام المادة )٤٦( وذلك لمدة سبع سنوات على األقل.
وال يجوز قبول القيد ألول مرة بجداول المحامين أمام محاكم االستئناف لمن يكون قد انقطع عن مزاولة األعمال
القانونية النظيرة مدة تجاوز عشر سنوات .$ab35$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
