WITH ins_art_law17_37 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 37, $al37$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — في القبول للمرافعة أمام محاكم االستئن ا ف$al37$, $ab37$للمحام ي المقيد بجدول محاكم االستئناف حق الحضور والمرافعة أمام جميع محاكم االستئناف ومحاكم القضاء
