WITH ins_art_law17_39 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 39, $al39$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — في القبول للمرافعة أمام محاكم االستئن ا ف$al39$, $ab39$يشترط لقبول طلب القيد بجدول المحامين أمام محكمة النقض أن يكون طالب القيد من الفئات اآلتية :
١ - المحامون المقبولون أمام محاكم االستئناف الذين يكون قد مضى على اشتغالهم بالمحاماة فعال أمام هذه
المحاكم عشر سنوات على األقل وكانت لهم أبحاث أو مذكرات أو فئاوى قانونية مبتكرة.
٢ - الشاغلون لوظيفة أستاذ ف ي مادة القانون بالجامعات المصرية .
٣ - المستشارون السابقون بالمحاكم وما يعادلها من وظائف الهيئات القضائية .$ab39$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
