INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab39$يشترط لقبول طلب القيد بجدول المحامين أمام محكمة النقض أن يكون طالب القيد من الفئات اآلتية :
١ - المحامون المقبولون أمام محاكم االستئناف الذين يكون قد مضى على اشتغالهم بالمحاماة فعال أمام هذه
المحاكم عشر سنوات على األقل وكانت لهم أبحاث أو مذكرات أو فئاوى قانونية مبتكرة.
٢ - الشاغلون لوظيفة أستاذ ف ي مادة القانون بالجامعات المصرية .
٣ - المستشارون السابقون بالمحاكم وما يعادلها من وظائف الهيئات القضائية .$ab39$, '1983-03-31', 'active', NULL FROM ins_art_law17_39;

WITH ins_art_law17_40 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 40, $al40$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — في القبول للمرافعة أمام محاكم االستئن ا ف$al40$, $ab40$يقدم طلب القيد ف ي جدول المحامين المقبولين أمام محكمة النقض والمحكمة االدارية العليا الى لجنة تشكل برئاسة
رئيس محكمة النقض أو أحد نوابه وعضوية النائب العام أو أحد مساعديه ونقيب المحامين أو وكيل النقابة
وعضوين يندبهما مجلس النقابة سنويا من بين أعضائه ويبلغ قرار اللجنة بالقبول أو الرفض الى الطالب والى
النقابة العامة.$ab40$
