WITH ins_art_law17_43 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 43, $al43$الباب األول — في القيد بجدول المحامي ن — الفصل السابع — في جدول المحامين غير المشتغلي ن$al43$, $ab43$للمحام ي الذي يرغب ف ي اعتزال المحاماة أن يطلب الى لجنة قبول المحامين المنصوص عليها ف ي المادة )١٦(
نقل اسمه الى جدول المحامين غير المشتغلين .
وعلى المحام ي أن يطلب أيضا نقل اسمه الى جدول غير المشتغلين إذا تولى احدى الوظائف أو األعمال الت ي ال
يجوز الجمع بينها وبين المحاماة أو إذا كف عن مزاولة المهنة ويتعين عليه أن يخطر لجنة القبول بذلك خالل
ثالثين يوما .
وعلى االدارات القانونية ف ي الجهات الت ي يجوز لمحاميها مزاولة أعمال المحاماة طبقا ألحكام هذا القانون اخطار
النقابة بأى تغيير يطرأ على أعضاء هذه االدارات بما يستوجب نقل اسم العضو الى جدول غير المشتغلين .$ab43$
  FROM laws WHERE law_no = 17 AND law_year = 1983
