WITH ins_art_law17_45 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 45, $al45$الباب األول — في القيد بجدول المحامي ن — الفصل السابع — في جدول المحامين غير المشتغلي ن$al45$, $ab45$يجوز لمن ينقل اسمه الى جدول غير المشتغلين أن يطلب اعادة قيده إذا كان من المحامين السابق قيدهم بجدول
المحامين أمام محاكم االستئناف أو م حكمة النقض .
فإذا كان من غير هؤالء فال يجوز اعادة قيده اال إذا كان قد مارس أعماال نظيرة ألعمال المحاماة خالل المدة الت ي
نقل فيها اسمه الى جدول غير المشتغلين.
وفى جميع األحوال يشترط أال يزيد انقطاع المحام ي عن ممارسة أعمال المحاماة أو األعمال النظيرة لها على
خمس عشرة سنة، مع عدم االخالل بحقه ف ي أن يطلب قيده من جديد ف ي الجدول العام إذا توافرت فيه شروط هذا
القيد.
ويجوز لمن ال يتوافر فيه شروط هذه المادة من المقيدين بجدول غير المشتغلين أن يعدلوا أوضاعهم خالل سنة
من تاريخ العمل بهذا القانون.$ab45$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
