وتدريس القانون ف ي الجامعات .
ويصدر قرار من وزير العدل بعد موافقة مجلس النقابة العامة بما يعتبر من األعمال القانونية األخرى الت ي تعد
نظيرة ألعمال المحاماة .$ab46$
