  SELECT id, 50, $al50$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في حقوق المحامي ن$al50$, $ab50$ال يجوز القبض على محام أو حبسه احتياطيًا لما ينسب إليه ف ي الجرائم المنصوص عليها ف ي المادة السابقة
وجرائم القذف والسب واإلهانة بسبب أقوال أو كتابات صدرت منه أثناء أو بسبب ممارسته أى من أعمال المهنة
المشار إليها ف ي هذا القانون، ويحرر ف ي هذه الحالة مذكرة بما حدث وتحال إلى النيابة العامة وتبلغ صورتها إلى
مجلس النقابة، وللنائب العام أن يتخذ اإلجراءات إذا كان ما وقع من المحام ي يشكل جريمة يعاقب عليها ف ي قانون
العقوبات، أو أن يحيله إلى مجلس النقابة إذا كان ما وقع منه مجرد إخالل بالنظام أو الواجب المهنى وفى هذه
الحالة تجرى المحاكمة ف ي جلسة سرية.
وال يجوز أن يشترك ف ي نظر الدعوى القاضى أو أحد أعضاء الهيئة الت ي وقع أمامها الفعل المؤثم. )٥ ($ab50$
