INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab50$ال يجوز القبض على محام أو حبسه احتياطيًا لما ينسب إليه ف ي الجرائم المنصوص عليها ف ي المادة السابقة
وجرائم القذف والسب واإلهانة بسبب أقوال أو كتابات صدرت منه أثناء أو بسبب ممارسته أى من أعمال المهنة
المشار إليها ف ي هذا القانون، ويحرر ف ي هذه الحالة مذكرة بما حدث وتحال إلى النيابة العامة وتبلغ صورتها إلى
مجلس النقابة، وللنائب العام أن يتخذ اإلجراءات إذا كان ما وقع من المحام ي يشكل جريمة يعاقب عليها ف ي قانون
العقوبات، أو أن يحيله إلى مجلس النقابة إذا كان ما وقع منه مجرد إخالل بالنظام أو الواجب المهنى وفى هذه
الحالة تجرى المحاكمة ف ي جلسة سرية.
وال يجوز أن يشترك ف ي نظر الدعوى القاضى أو أحد أعضاء الهيئة الت ي وقع أمامها الفعل المؤثم. )٥ ($ab50$, '1983-03-31', 'active', NULL FROM ins_art_law17_50;

WITH ins_art_law17_51 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 51, $al51$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في حقوق المحامي ن$al51$, $ab51$ال يجوز التحقيق مع محام أو تفتيش مكتبه إال بمعرفة أحد أعضاء النيابة العامة أو قاضى التحقيق في األحوال
الت ي يجيز فيها القانون ذلك. )٨(
وفي غير حاالت التلبس، ال يجوز لمأمور الضبط القضائى احتجاز أو القبض على المحام ي الموجه له اتهام
بارتكاب جناية أو جنحة أثناء مباشرته حق الدفاع، ويتعين عرض األمر فو ًرا على المحام ي العام األول لنيابة
االستئناف المختصة. )٩ (
ويجب على النيابة العامة أن تخطر مجلس النقابة أو مجلس النقابة الفرعية قبل الشروع ف ي تحقيق أية شكوى ضد
محام بوقت مناسب. وللنقيب أو رئيس النقابة الفرعية إذا كان المحام ي متهما بجناية أو جنحة خاصة بعمله أن
يحضر هو أو من ينيبه من المحامين، التحقيق .
ولمجلس النقابة، ولمجلس النقابة الفرعية المختص طلب صور التحقيق ب غير رسوم .$ab51$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
