WITH ins_art_law17_52 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 52, $al52$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في حقوق المحامي ن$al52$, $ab52$للمحام ي حق االطالع على الدعاوى واألوراق القضائية والحصول على البيانات المتعلقة بالدعاوى الت ي يباشرها .
ويجب على جميع المحاكم والنيابات ودوائر الشرطة ومأموريات الشهر العقارى وغيرها من الجهات الت ي
يمارس المحام ي مهمته أمامها أن تقدم له الت سهيالت الت ي يقتضيها القيام بواجبه وتمكينه من االطالع على
األوراق والحصول على البيانات وحضور التحقيق مع موكله وفقا ألحكام القانون وال يجوز رفض طلباته دون
مسوغ قانونى.
ويجب اثبات جميع ما يدور ف ي الجلسة ف ي محضرها .$ab52$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
