WITH ins_art_law17_58 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 58, $al58$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في حقوق المحامي ن$al58$, $ab58$ال يجوز ف ي غير المواد الجنائية التقرير بالطعن أمام محكمة النقض أو المحكمة االدارية العليا اال من المحامين
المقررين لديها سواء كان ذلك عن أنفسهم أو بالوكالة من الغير.
كما ال يجوز تقديم صحف االستئناف أو تقديم صحف الدعاوى أمام محكمة القضاء اإلداري اال إذا كانت موقعة
من أحد المحامين المقررين أمامها .
وكذلك ال يجوز تقديم صحف الدعاوى وطلبات أوامر األداء للمحاكم االبتدائية واالدارية اال إذا كانت موقعة من
أحد المحامين المقررين أمامها على األقل.
وكذلك ال يجوز تقديم صحف الدعاوى أو طلبات أوامر األداء للمحاكم الجزئية ا ال إذا كانت موقعة من أحد
المحامين المشتغلين وذلك متى بلغت أو جاوزت قيمة الدعوى أو أمر األداء خمسين جنيها .
ويقع باطال كل اجراء يتم بالمخالفة ألحكام هذه المادة .$ab58$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
