WITH ins_art_law17_60 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 60, $al60$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في حقوق المحامي ن$al60$, $ab60$يشترط أن يتضمن عقد أو نظام تأسيس أى شركة من الشركات الت ي يشترط القانون أن يكون لها مراقب حسابات،
تعيين مستشار قانونى من المحامين المقبولين للمرافعة أمام محاكم االستئناف على األقل.
وال يجوز قيد هذه الشركات ف ي السجل التجارى أو تجديد قيدها قبل التحقق من استيفاء ذلك عن طريق إيداع
صورة من التوكيل الصادر للمحام ي من ممثلها القانونى معتمدًا من نقابة المحامين الفرعية الت ي يتبعها المحام ي .
ويجب على المحام ي خالل ثالثين يو ًما على األكثر من تاريخ التوكيل إيداع صورة منه بالنقابة العامة أو النقابة
الفرعية وسداد مبلغ خمسين جني ًها مصريًا سنويًا عن كل وكالة من هذه الشركات لصالح صندوق الرعاية
الصحية واالجتماعية تخصص لدعم المحامين الشبان وتدريبهم ورعايتهم، ويسرى على هذا المبلغ أحكام
االشتراك المنصوص عليها ف ي المادتين )١٦٩( و)١٧٠( من هذا القانون، وال يجوز اإلعفاء منه .
ويسرى هذا الحكم على الشركات المذكورة القائمة عند العمل بأحكام هذا القانون وذلك عند تجديد قيدها بالسجل
التجارى. )٥ ($ab60$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
