WITH ins_art_law17_62 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 62, $al62$الباب األول — في القيد بجدول المحامي ن — الفصل األول — في حقوق المحامي ن$al62$, $ab62$على المحام ي أن يلتزم في سلوكه المهنى والشخصى بمبادئ الشرف واالستقامة والنزاهة وأن يقوم بجميع
الواجبات الت ي يفرضها عليه هذا القانون والنظام الداخل ي للنقابة ولوائحها وآداب المحاماة وتقاليدها .
ويضع مجلس النقابة العامة مدونة للسلوك المهنى للمحاماة، تقرها الجمعية العمومية للنقابة وتنشر المدونة، وكل
تعديل لها، في الوقائع المصرية وتكون ملزمة ألعضاء النقابة، ويترتب على مخالفتهم ألحكامها انعقاد مسئوليتهم
المهنية عن األفعال الت ي ترتكب بالمخالفة ألحكام مدونة السلوك. )٩ ($ab62$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
