WITH ins_art_law17_98 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 98, $al98$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al98$, $ab98$كل محام يخالف أحكام هذا القانون أو النظام الداخل ي للنقابة أو يخل بواجبات مهنته أو يقوم بعمل ينال من شرف
المهنة أو يتصرف تصرفا شائنا يحط من قدر المهنة يجازى باحدى العقوبات التأديبية التالية :
١ - االنذار.
٢ - اللوم.
٣ - المنع من مزاولة المهنة.
٤ - محو االسم نهائيا من الجدول.
ويجب أال تتجاوز عقوبة المنع من مزاولة المهنة ثالث سنوات. وال يترتب على محو األسم نهائيا من الجدول
المساس بالمعاش المستحق .$ab98$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab98$كل محام يخالف أحكام هذا القانون أو النظام الداخل ي للنقابة أو يخل بواجبات مهنته أو يقوم بعمل ينال من شرف
المهنة أو يتصرف تصرفا شائنا يحط من قدر المهنة يجازى باحدى العقوبات التأديبية التالية :
١ - االنذار.
٢ - اللوم.
٣ - المنع من مزاولة المهنة.
٤ - محو االسم نهائيا من الجدول.
ويجب أال تتجاوز عقوبة المنع من مزاولة المهنة ثالث سنوات. وال يترتب على محو األسم نهائيا من الجدول
المساس بالمعاش المستحق .$ab98$, '1983-03-31', 'active', NULL FROM ins_art_law17_98;

WITH ins_art_law17_99 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 99, $al99$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al99$, $ab99$يجوز لهيئة مكتب النقابة العامة لفت نظر المحام ي أو توقيع عقوبة اإلنذار عليه. )٨ (
كما يجوز لها أن تأمر بوقف المحام ي الذي أقيمت ضده الدعوى التأديبية عن مزاولة المهنة احتياطيًا، إلى أن
يفصل في هذه الدعوى وذلك بعد سماع أقواله، ويجوز للمحام ي التظلم لمجلس النقابة خالل ثالثين يو ًما، ولمجلس
النقابة إما إلغاء القرار أو عرض األمر على الدائرة المختصة بالتأديب للفصل في القرار والموضوع. )٨ (
ويعرض هذا األمر على مجلس التأديب المنصوص عليه ف ي المادة ١٠٧ من هذا القانون خالل الثالثين يوما
التالية لتاريخ صدوره ويقرر المجلس خالل عشرة أيام من تاريخ عرض األمر عليه بعد سماع أقوال المحام ي إما
االستمرار ف ي منعه من مزاولة المهنة احتياطيا أو السماح له باالستمرار ف ي مزاولتها إلى أن يفصل ف ي الدعوى
التأديبية المرفوعة عليه.
وعلى مجلس النقابة الفرعية أن يندب محاميا آخر لمباشرة قضايا المحام ي الموقوف طوال فترة وقفه .$ab99$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab99$يجوز لهيئة مكتب النقابة العامة لفت نظر المحام ي أو توقيع عقوبة اإلنذار عليه. )٨ (
كما يجوز لها أن تأمر بوقف المحام ي الذي أقيمت ضده الدعوى التأديبية عن مزاولة المهنة احتياطيًا، إلى أن
يفصل في هذه الدعوى وذلك بعد سماع أقواله، ويجوز للمحام ي التظلم لمجلس النقابة خالل ثالثين يو ًما، ولمجلس
النقابة إما إلغاء القرار أو عرض األمر على الدائرة المختصة بالتأديب للفصل في القرار والموضوع. )٨ (
ويعرض هذا األمر على مجلس التأديب المنصوص عليه ف ي المادة ١٠٧ من هذا القانون خالل الثالثين يوما
التالية لتاريخ صدوره ويقرر المجلس خالل عشرة أيام من تاريخ عرض األمر عليه بعد سماع أقوال المحام ي إما
االستمرار ف ي منعه من مزاولة المهنة احتياطيا أو السماح له باالستمرار ف ي مزاولتها إلى أن يفصل ف ي الدعوى
التأديبية المرفوعة عليه.
وعلى مجلس النقابة الفرعية أن يندب محاميا آخر لمباشرة قضايا المحام ي الموقوف طوال فترة وقفه .$ab99$, '1983-03-31', 'active', NULL FROM ins_art_law17_99;

