WITH ins_art_law17_116 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 116, $al116$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al116$, $ab116$للنيابة العامة وللمحامى المحكوم عليه حق الطعن ف ي القرارات الصادرة من مجلس التأديب المنصوص عليه ف ي
المادة ١٠٧ وذلك خالل خمسة عشر يوما بالنسبة الى النيابة من تاريخ صدور القرار وبالنسبة الى المحام ي من
تاريخ اعالنه بالقرار أو تسلمه صورته .
ويفصل ف ي هذا الطعن مجلس يؤلف من أربعة من مستشارى محكمة النقض تعينهم جمعيتها العمومية كل سنة
ومن النقيب أو وكيل النقابة وعضوين من مجلس النقابة .
وللمحامى الذي رفعت عليه الدعوى التأديبية أن يختار أحد هذين العضوين .
وال يجوز أن يشترك ف ي المجلس أحد أعضاء مجلس التأديب الذي أصدر القرار المطعون عليه.
والقرار الذي يصدر يكون نهائيا .$ab116$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab116$للنيابة العامة وللمحامى المحكوم عليه حق الطعن ف ي القرارات الصادرة من مجلس التأديب المنصوص عليه ف ي
