والقرار الذي يصدر يكون نهائيا .$ab116$, '1983-03-31', 'active', NULL FROM ins_art_law17_116;

WITH ins_art_law17_117 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 117, $al117$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al117$, $ab117$إذا حصل من محى اسمه من جدول المحامين على أدلة جديدة تثبت براءته جاز له بعد موافقة مجلس النقابة أن
يطعن ف ي القرار الصادر بمحو اسمه بطريق التماس اعادة النظر أمام مجلس تأديب المحامين بمحكمة النقض،
فاذا رفض المجلس طلبه جاز له تجديده بعد مضى خمس سنوات ويشترط أن يقدم أدلة غير األدلة السابق تقديمها .
وال يجوز تجديد الطلب أكثر من مرة .
ويرفع االلتماس بعريضة تقدم الى المجلس ويكون القرار الذي يصدر برفضه نهائيا .$ab117$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab117$إذا حصل من محى اسمه من جدول المحامين على أدلة جديدة تثبت براءته جاز له بعد موافقة مجلس النقابة أن
يطعن ف ي القرار الصادر بمحو اسمه بطريق التماس اعادة النظر أمام مجلس تأديب المحامين بمحكمة النقض،
فاذا رفض المجلس طلبه جاز له تجديده بعد مضى خمس سنوات ويشترط أن يقدم أدلة غير األدلة السابق تقديمها .
