ويرفع االلتماس بعريضة تقدم الى المجلس ويكون القرار الذي يصدر برفضه نهائيا .$ab117$, '1983-03-31', 'active', NULL FROM ins_art_law17_117;

WITH ins_art_law17_118 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 118, $al118$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al118$, $ab118$لمن صدر ضده قرار تأديبى بمحو اسمه من جدول المحامين أن يطلب بعد مضى سبع سنوات كاملة على األقل
من لجنة قبول المحامين المنصوص عليها ف ي المادة ١٦ من هذا القانون قيد اسمه ف ي الجدول فاذا رأت اللجنة أن
المدة الت ي مضت من وقت صدور القرار بمحو اسمه كافية الصالح شأنه وازالة أثر ما وقع منه أمرت بقيد اسمه
بالجدول وحسبت أقدميته من تاريخ هذا القرار.
وللجنة أن تسمع أقوال الطالب وتصدر قرارها بعد أخذ رأى مجلس النقابة فاذا قضت برفض طلبه جاز له تجديده
بعد مضى خمس سنوات .
وال يجوز تجديد الطلب أكثر من مرة .
والقرار الذي يصدر برفض الطلب يكون نهائيا.$ab118$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
