WITH ins_art_law17_119 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 119, $al119$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al119$, $ab119$تسجل ف ي سجل خاص بالنقابة القرارات التأديبية النهائية الصادرة ضد المحام ي ويشار اليها ف ي الملف الخاص
به. وتخطر بها النقابات الفرعية وأقالم كتاب المحاكم والنيابات وتنشر القرارات النهائية بمجلة المحاماة دون ذكر
أسماء من تناولتهم القرارات .
واذا كان القرار صادرا بمحو االسم من الجدول أو المنع من مزاولة المهنة فينشر منطوقه دون األسباب ف ي
الوقائع المصرية .
ويتولى مجلس النقابة الفرعية تنفيذ القرارات التأديبية على أن تعاونه النيابة العامة متى طلب منها ذلك .
القسم الثان ى
في نظام نقابة المحامي ن
باب تمهيد ى$ab119$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
