  SELECT id, 120, $al120$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al120$, $ab120$نقابة المحامين مؤسسة مهنية مستقلة تضم المحامين ف ي جمهورية مصر العربية المقيدين بجداولها، وتتمتع
