) أ ( تنظيم ممارسة مهنة المحاماة وضمان حسن أدائها .
)ب( كفالة حق الدفاع للمواطنين وتقديم المساعدات القضائية لغير القادرين منهم .
)جـ( العناية بمصالح أعضائها وتزكية روح التعاون بينهم وضمان استقاللهم ف ي أداء رسالتهم .
)د( تشجيع البحوث القانونية ودراسات الشريعة االسالمية .
)هـ( التعاون مع النقابات المهنية والمنظمات المماثلة ف ي الدول العربية والدول األفريقية وغيرها للعمل على
خدمة األهداف القومية لألمة العربية ونصرة قضايا الحرية والسالم والتقدم .$ab121$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
