WITH ins_art_law17_122 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 122, $al122$الباب األول — في القيد بجدول المحامي ن — الفصل الخامس — المسئولية التأديبي ة$al122$, $ab122$للنقابة ف ي سبيل تحقيق أهدافها المبينة بالمادة السابقة التعاون مع النقابات المهنية األخرى والجمعيات القانونية
العلمية والمنظمات المماثلة ف ي الدول العربية واتحاداتها تحقيقا لألهداف القومية لألمة العربية ف ي أن يكون
القانون ف ي خدمة قضايا الحرية وأداة لمناهضة االستعمار والعنصرية بجميع أشكالها .
وللنقابة أيضا التعاون مع اتحادات المحامين ومنظماتها الدولية لتبادل الخبرات حول نظم القضاء والمحاماه
واالرتقاء بمستوى المهنة وتأكيد رسالتها ف ي الدفاع عن حقوق االنسان .$ab122$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
