WITH ins_art_law17_124 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 124, $al124$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al124$, $ab124$تتكون الجمعية العمومية للنقابة العامة سنويا من المحامين المقبولين أمام محكمة النقض ومحاكم االستئناف
والمحاكم االبتدائية الذين سددوا رسوم االشتراك المستحقة عليهم أو أعفوا منها حتى آخر السنة السابقة على موعد
انعقاد الجمعية العمومية وقبل اجتماعها بشهر على األقل. )١(
وتنعقد الجمعية العمومية سنويا ف ي شهر يونيه ف ي مقر نقابة المحامين بالقاهرة وال يكون اجتماعها صحيحا اال إذا
حضره ثلث األعضاء على األقل أو ثالثة آالف عضو أيهما أقل فاذا لم يتوافر هذا العدد أجل االجتماع أسبوعين
ويكون االجتماع الثانى صحيحا إذا حضره ألف وخمسمائ ة عضو من أعضائها على األقل فاذا لم يكتمل العدد ف ي
هذا االجتماع أعيدت الدعوة الجتماع يعقد خالل أسبوعين وتكرر الدعوة حتى يكتمل العدد المطلوب .
وفى جميع األحوال يجوز لمجلس النقابة تأجيل انعقاد الجمعية العمومية الى ما بعد انتهاء العطلة القضائية .$ab124$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
