وفى جميع األحوال يجوز لمجلس النقابة تأجيل انعقاد الجمعية العمومية الى ما بعد انتهاء العطلة القضائية .$ab124$, '1983-03-31', 'active', NULL FROM ins_art_law17_124;

WITH ins_art_law17_125 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 125, $al125$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al125$, $ab125$يرأس النقيب اجتماع الجمعية العمومية وفى حالة غيابه ينوب عنه أقدم الوكيلين ممن يزاول المهنة مستقال وفى
حالة غيابه، ينوب عنه الوكيل اآلخر.
ويعلن رئيس الجمعية افتتاح اجتماعها بعد التحقق من توافر النصاب الالزم النعقادها .
كما يعلن فض االجتماع ويتولى أمين عام النقابة أمانة االجتماع وعند غيابه يختار رئيس الجمعية أمينا لالجتماع.
وتختار الجمعية العمومية اثنين من بين أعضائها فارزى أصوات.$ab125$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab125$يرأس النقيب اجتماع الجمعية العمومية وفى حالة غيابه ينوب عنه أقدم الوكيلين ممن يزاول المهنة مستقال وفى
حالة غيابه، ينوب عنه الوكيل اآلخر.
ويعلن رئيس الجمعية افتتاح اجتماعها بعد التحقق من توافر النصاب الالزم النعقادها .
كما يعلن فض االجتماع ويتولى أمين عام النقابة أمانة االجتماع وعند غيابه يختار رئيس الجمعية أمينا لالجتماع.
وتختار الجمعية العمومية اثنين من بين أعضائها فارزى أصوات.$ab125$, '1983-03-31', 'active', NULL FROM ins_art_law17_125;

WITH ins_art_law17_126 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 126, $al126$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al126$, $ab126$عالوة على ما ورد بشأنه نص خاص ف ي هذا القانون، تختص الجمعية العمومية ف ي اجتماعها السنوى بما يأت ى:
١ - النظر ف ي تقرير مجلس النقابة ومراقب ي الحسابات عن الحساب الختام ي للنقابة عن السنة المنتهية واقرار
الميزانية التقديرية عن السنة المقبلة .
٢ - تعديل رسوم القيد واالشتراك ورسوم الدمغة الت ي يؤديها المحامون لصالح النقابة بناء على اقتراح مجلس
النقابة .
٣ - تعديل مقدار المعاش المقرر للمحامين والمستحقين عنهم وتعديل قواعد استحقاق المعاش بناء على اقتراح
مجلس النقابة ووفقا لتقرير خبيرين اكتواريين يختارهما مجلس النقابة .$ab126$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
