يعرض لنظر المسائل العاجلة الت ي طرأت بعد توجيه الدعوة وتمت دراستها .$ab127$, '1983-03-31', 'active', NULL FROM ins_art_law17_127;

WITH ins_art_law17_128 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 128, $al128$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al128$, $ab128$للجمعية العمومية أن تعقد اجتماعات غير عادية بنا ًء على دعوة مجلس النقابة العامة، أو بنا ًء على طلب كتابى يقم
إلى النقيب من عدد ال يقل عن خمس نقابات فرعية، أو ألفى عضو من أعضاء جمعية االنتخاب يكون مصدقًا
على توقيعاتهم من النقابة الفرعية المختصة أو مصلحة الشهر العقارى، ويجب أن يبين في الطلب أسبابه وجدول
األعمال المقترح، ويتولى النقيب توجيه الدعوة لالجتماع خالل ثالثين يو ًما على األكثر من تاريخ الطلب .
وإذا لم يوجه النقيب الدعوة خالل المدة المذكورة، اجتمعت الجمعية العمومية غير العادية بقوة القانون في اليوم
التالى النتهاء تلك المدة. )٨ ($ab128$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab128$للجمعية العمومية أن تعقد اجتماعات غير عادية بنا ًء على دعوة مجلس النقابة العامة، أو بنا ًء على طلب كتابى يقم
إلى النقيب من عدد ال يقل عن خمس نقابات فرعية، أو ألفى عضو من أعضاء جمعية االنتخاب يكون مصدقًا
على توقيعاتهم من النقابة الفرعية المختصة أو مصلحة الشهر العقارى، ويجب أن يبين في الطلب أسبابه وجدول
األعمال المقترح، ويتولى النقيب توجيه الدعوة لالجتماع خالل ثالثين يو ًما على األكثر من تاريخ الطلب .
وإذا لم يوجه النقيب الدعوة خالل المدة المذكورة، اجتمعت الجمعية العمومية غير العادية بقوة القانون في اليوم
التالى النتهاء تلك المدة. )٨ ($ab128$, '1983-03-31', 'active', NULL FROM ins_art_law17_128;

WITH ins_art_law17_129 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 129, $al129$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al129$, $ab129$إذا كان طلب عقد الجمعية العمومية غير العادية لسحب الثقة من النقيب أو عضو أو أكثر من أعضاء مجلس
النقابة، فيشترط لصحة طلب انعقادها توقيع عدد ال يقل عن خمس عدد األصوات الحاصل عليها النقيب أو العضو
المطلوب سحب الثقة منه مصدقًا على توقيعاتهم من النقابة الفرعية المختصة وموض ًحا فيه أسباب الطلب وأسانيده
ومستنداته، ويجب النعقادها حضور عدد ال يقل عن عشر عدد أعضاء الجمعية العمومية، وتكون رئاستها في هذه
الحالة ألكثر األعضاء سنًا من غير أعضاء مجلس النقابة .
وفي حالة عدم اكتمال نصاب انعقادها يعتبر الطلب كأن لم يكن.
وال يجوز تقديم هذا الطلب قبل مرور عام من تاريخ تشكيل مجلس النقابة العامة إال إذا كانت أسباب سحب الثقة
تشكل جريمة جنائية، كما ال يجوز إعادة تقديم الطلب لذات األسباب الت ي رفضتها الجمعية العامة صراحة أو
ضمنًا قبل مرور عام على تقديم الطلب المشار إليه. )٨ ($ab129$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab129$إذا كان طلب عقد الجمعية العمومية غير العادية لسحب الثقة من النقيب أو عضو أو أكثر من أعضاء مجلس
النقابة، فيشترط لصحة طلب انعقادها توقيع عدد ال يقل عن خمس عدد األصوات الحاصل عليها النقيب أو العضو
