وال يجوز تقديم هذا الطلب قبل مرور عام من تاريخ تشكيل مجلس النقابة العامة إال إذا كانت أسباب سحب الثقة
تشكل جريمة جنائية، كما ال يجوز إعادة تقديم الطلب لذات األسباب الت ي رفضتها الجمعية العامة صراحة أو
ضمنًا قبل مرور عام على تقديم الطلب المشار إليه. )٨ ($ab129$, '1983-03-31', 'active', NULL FROM ins_art_law17_129;

WITH ins_art_law17_130 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 130, $al130$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al130$, $ab130$تصدر قرارات الجمعية العمومية باألغلبية المطلقة ألصوات الحاضرين، فاذا تساوت األصوات يرجح الجانب
الذي فيه رئيس الجمعية، ويحرر محضر بنتيجة االجتماع يثبت ف ي دفتر خاص ويوقع عليه من رئيس الجمعية
واألمين العام وفارزى األصوات.
ويبين النظام الداخل ي للنقابة اجراءات دعوة الجمعية العمومية وانعقادها وكيفية سير العمل فيها .$ab130$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab130$تصدر قرارات الجمعية العمومية باألغلبية المطلقة ألصوات الحاضرين، فاذا تساوت األصوات يرجح الجانب
الذي فيه رئيس الجمعية، ويحرر محضر بنتيجة االجتماع يثبت ف ي دفتر خاص ويوقع عليه من رئيس الجمعية
واألمين العام وفارزى األصوات.
ويبين النظام الداخل ي للنقابة اجراءات دعوة الجمعية العمومية وانعقادها وكيفية سير العمل فيها .$ab130$, '1983-03-31', 'active', NULL FROM ins_art_law17_130;

WITH ins_art_law17_131 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 131, $al131$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al131$, $ab131$يُشكل مجلس النقابة العامة من:
١ - نقيب المحامين .
٢ – ثمانية وعشرين عض ًوا.ويُراعى في انتخابهم اآلتى :
أوالً –أن يكون نصف عدد األعضاء على األقل من المحامين المقبولين للمرافعة أمام محكمة النقض أو محاكم
االستئناف .
ثانيًا –أن يمثل المحامون في دائرة كل محكمة استئناف بعضو واحد.
ثالثًا –أن يمثل المحامون بالهيئات العامة والوحدات االقتصادية وشركات قطاع األعمال بثالثة أعض اء .
وال يجوز الجمع بين الترشح لمنصب النقيب والترشح لعضوية مجلس النقابة، كما ال يجوز الترشح لمثيل أكثر
من فئة من الفئات المذكورة في هذه المادة .
ويتم انتخاب النقيب وجميع أعضاء النقابة من الجمعية العمومية للنقابة. )٨ ($ab131$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab131$يُشكل مجلس النقابة العامة من:
