WITH ins_art_law17_134 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 134, $al134$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al134$, $ab134$يكون الترشيح لعضوية المجلس بطلب يقدم من المرشح الى مجلس النقابة ف ي الميعاد الذي يحدده لقبول طلبات
الترشيح على أن يكون قبل الموعد المحدد إلجراء االنتخاب بأربعين يوما على األقل.
ويعد مجلس النقابة قائمة المرشحين خالل عشرة أيام على األكثر من قفل باب الترشيح وتعلن على المحامين ف ي
النقابات الفرعية. ولمن أغفل ادراج اسمه بها أن يتظلم الى مجلس النقابة أو أن يطعن في قراره أمام محكمة
استئناف القاهرة خالل عشرة أيام من تاريخ نشر كشوف المرشحين ويفصل ف ي الطعن على وجه االستعجال.
)٢٥ ($ab134$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
