ويعد مجلس النقابة قائمة المرشحين خالل عشرة أيام على األكثر من قفل باب الترشيح وتعلن على المحامين ف ي
النقابات الفرعية. ولمن أغفل ادراج اسمه بها أن يتظلم الى مجلس النقابة أو أن يطعن في قراره أمام محكمة
استئناف القاهرة خالل عشرة أيام من تاريخ نشر كشوف المرشحين ويفصل ف ي الطعن على وجه االستعجال.
)٢٥ ($ab134$, '1983-03-31', 'active', NULL FROM ins_art_law17_134;

