ويتولى النقيب رئاسته .
ويشترط أن يكون النقيب وأحد الوكيلين على األقل ممن يزاوالن المهنة مستقلين.
ويجوز للمجلس أن يعين من بين أعضائه أمينا عاما مساعدا أو أمينا مساعدا للصندوق ويكونون أعضاء بهيئة
المكتب .
ويحدد النظام الداخل ي للنقابة اختصاصات أعضاء المكتب وتوزيع األعمال بين أعضاء المجلس وتشكيل لجانه
واختصاصاتها .$ab137$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
