WITH ins_art_law17_139 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 139, $al139$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al139$, $ab139$يعقد مجلس النقابة العامة اجتماعا دوريا كل خمسة عشر يوما على األقل بناء على دعوة النقيب. ويكون اجتماعه
صحيحا إذا حضره أكثر من نصف أعضائه .
وتصدر قراراته بأغلبية أصوات الحاضرين، فاذا تساوت األصوات يرجح الجانب الذي منه الرئيس .
ويجوز أن يعقد المجلس اجتماعات غير عادية بناء على دعوة من النقيب أو بناء على طلب عشرة على األقل من
أعضاء المجلس أو بناء على طلب مجالس خمس نقابات فرعية على األقل، وذلك بكتاب يوجه الى النقيب مرفقا
به جدول األعمال المقترح .$ab139$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
