WITH ins_art_law17_141 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 141, $al141$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al141$, $ab141$تسقط العضوية عن النقيب وعن أى عضو ف ي المجلس إذا فقد أى شرط من شروط صالحية الترشيح المنصوص
عليها ف ي هذا القانون .
ويصدر بذلك قرار من المجلس بأغلبية ثلثى أعضائه بعد سماع أقوال العضو إذا كان لذلك مقتض .
وللمجلس أن يقرر بنفس األغلبية اسقاط عضوية من يتغيب عن جلساته أربع مرات متتالية أو ثمانى مرات
منقطعة خالل السنة الواحدة بغير عذر يقبله المجلس على أن يخطر العضو لسماع أقوال قبل تقرير اسقاط
العضوية.
وللجمعية العمومية للنقابة الفرعية أو لمجلس نقابتها أن يطلب من مجلس النقابة العامة اسقاط العضوية عن عضو
المجلس المنتخب من النقابة الفرعية ف ي حالة الغياب المبين ف ي الفقرة السابقة.
وللعضو الذي أسقت عضويته حق الطعن أمام الدائرة الجنائية لمحكمة النقض ف ي القرار الذي يصدر باسقاط
عضويته بتقرير يقدمه الى محكمة النقض خالل أربعين يوما من تاريخ اخطاره بالقرار.$ab141$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
