WITH ins_art_law17_142 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 142, $al142$الباب األول — النقابة العامة — الفصل األول — الجمعية العمومي ة$al142$, $ab142$إذا شغل مركز النقيب ألي سبب وكانت المدة الباقية له تقل عن سنة يقوم أقدم الوكيلين مقامه بشرط أن يكون ممن
يزاول المهنة مستقال، فاذا زادت المدة الباقية على سنة يتعين على مجلس النقابة الدعوة الى انتخاب نقيب جديد
يكمل المدة الباقية للنقيب األصل ي وذلك خالل ستين يوما من شغل مركز النقيب .
وإذا شغل مكان أحد أعضاء المجلس ألي سبب كان، عين المجلس بدال منه للمدة الباقية من العضوية المرشح
الحاصل على األصوات التالية ف ي االنتخاب السابق مع مراعاة حكم المادة )١٣١(. واذا لم يوجد تعين على مجلس
النقابة الدعوة الى انتخاب عضو جديد يكمل المدة الباقية للعضو األصل ي، على أن يجرى االنتخاب خالل ستين
يوما من تاريخ شغل المكان.$ab142$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
