WITH ins_art_law17_150 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 150, $al150$الباب الثاني — النقابات الفرعي ة — الفصل األول — تشكيل النقابات الفرعية وهيئاته ا$al150$, $ab150$للجمعية العمومية أن تعقد اجتماعا غير عادى للنظر ف ي سحب الثقة من مجلس النقابة الفرعية أو من أحد أعضائه
بناء على طلب كتاب ي يقدم من مجلس النقابة الفرعية موقع من عدد من األعضاء ال يقل عن ثلث عدد أعضاء
الجمعية العمومية أو مائة عضو أيهما أقل. ويبلغ طلب عقد الجمعية الى مجلس النقابة العامة الذي يتولى بوجيه
الدعوة خالل ستين يوما على األكثر من تاريخ طلبها وندب أحد أعضائه لرئاسة اجتماعها واالشراف على
اجراءات ابداء الرأى فيها .
كما أن للجمعية العمومية أن تعقد اجتماعا غير عادى كلما رأى مجلس النقابة الفرعية ضرورة لذلك أو قدم به
طلب مسبق موقع عليه من ثلث عدد أعضاء الجمعية العمومية أو بناء على طلب مجلس النقابة العامة لطرح
موضوع عليه ألخذ الرأى فيه ويتولى مجلس النقابة الفرعية الدعوة الى االجتماع ف ي هذه الحاالت .$ab150$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
