WITH ins_art_law17_154 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 154, $al154$الباب الثاني — النقابات الفرعي ة — الفصل األول — تشكيل النقابات الفرعية وهيئاته ا$al154$, $ab154$تشكل هيئة مكتب مجلس النقابة الفرعية من النقيب واألمين العام وأمين الصندوق .
وينتخب مجلس النقابة الفرعية ف ي أول اجتماع له بعد تشكيله الوكيل واألمين العام وأمين الصندوق. ويشترط ف ي
النقيب أن يكون من المحامين الذين يزاولون المهنة استقالال المقبولين للمرافعة أمام محكمة النقض ممن مضى
على اشتغالهم بالمهنة عشرون سنة متصلة على األقل.
ويكون لهيئة المكتب كافة االختصاصات المخولة لهيئة مكتب النقابة العامة ف ي حدود اختصاص النقابة الفرعية .$ab154$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
