  SELECT id, 160, $al160$الباب الثاني — النقابات الفرعي ة — الفصل األول — تشكيل النقابات الفرعية وهيئاته ا$al160$, $ab160$تعين الجمعية العمومية ف ي اجتماعها السنو ي بناء على اقتراح مجلس النقابة العامة مراقبا للحسابات أو أكثر من
المقيدين بجدول المحاسبين وتحدد أتعابه. ويختص بمراجعة حسابات النقابة العامة والنقابات الفرعية وله ف ي سبيل
ذلك اقتراح النظام المالى الذي يكفل حسن سير العمل وأن يقوم بجرد سنوى للخزينة وحسابات العهد والمخازن
ف ي النقابة العامة وفى النقابات الفرعية ويعد تقريرا بمالحظاته عن كل ما تقدم يعرض على مجلس النقابة العامة.
وعليه خالل السنة موافاة أمين الصندوق بما قد يكون لديه من مالحظات .
ولمراقب الحسابات االطالع على دفاتر النقابة العامة والنقابات الفرعية وسجالتها ومستنداتها وطلب البيانات
وااليضاحات الت ي يرى لزوما لها.$ab160$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
