اقتراح أمين الصندوق .
ولمجلس النقابة العامة أن يحدد بناء على اقتراح أمين الصندوق، ما يودع من هذه األموال ف ي حسابات الودائع أو
ف ي الحسابات الجارية وما يتم استثماره منها ف ي سندات حكومية أو أوراق مالية وما يحتفظ به بخزينة النقابة
بصفة مستديمة للصرف منها ف ي الحاالت الطارئة.
ويكون الصرف من حسابات النقابة وفق ما يقضى به النظام المالى للنقابة وبتوقيع النقيب أو الوكيل وأمين
الصندوق أو األمين المساعد للصندوق .$ab165$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
