٢٤ للمحام ي أمام المحاكم االبتدائية إذا زادت مدة قيده ف ي هذا الجدول على ثالث سنوات .
٦٠ للمحام ي أمام محاكم االستئناف .
٨٠ للمحام ي أمام محكمة النقض.$ab168$, '1983-03-31', 'active', NULL FROM ins_art_law17_168;

WITH ins_art_law17_169 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 169, $al169$الباب الثاني — النقابات الفرعي ة — الفصل األول — تشكيل النقابات الفرعية وهيئاته ا$al169$, $ab169$على المحام ي أن يؤدى االشتراك السنوى وفق الفئات المبينة بالمادة السابقة ف ي ميعاد غايته آخر مارس من كل
سنة، ويتم السداد الى النقابة الفرعية الت ي يتبعها أو الى النقابة العامة .
وعلى النقابة الفرعية توريد ما حصلته من اشتراكات الى النقابة العامة بمجرد تحصيلها .
ومن يتأخر ف ي سداد االشتراك عن الموعد المشار اليه ال يقبل منه أى طالب وال تعطى له أى شهادة من النقابة
وال يتمتع بأى خدمة نقابية اال بعد أن يؤدى جميع االشتراكات المتأخرة .$ab169$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
