SELECT id, 1, $ab169$على المحام ي أن يؤدى االشتراك السنوى وفق الفئات المبينة بالمادة السابقة ف ي ميعاد غايته آخر مارس من كل
سنة، ويتم السداد الى النقابة الفرعية الت ي يتبعها أو الى النقابة العامة .
