WITH ins_art_law17_170 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 170, $al170$الباب الثاني — النقابات الفرعي ة — الفصل األول — تشكيل النقابات الفرعية وهيئاته ا$al170$, $ab170$يقوم أمين الصندوق بعد التاريخ المبين بالمادة السابقة بإنذار المتخلف باستبعاد اسمه بمقتضى اعالن ينشر ف ي
مجلة المحاماة خالل شهر ابريل من كل سنة، ومن يتخلف عن تأدية االشتراك حتى آخر يونيو يستبعد اسمه من
الجدول بقوة القانون.
فاذا أوفى االشتراكات المستحقة عليه أعيد اسمه الى الجدول بغير اجراءات وأحتسب له مدة االستبعاد ف ي األقدمية
والمعاش .
فاذا مضى على استبعاد المحام ي سنتان دون أن يؤدى االشتراكات المستحقة عليه وجب التنبيه عليه بالوفاء خالل
ثالثة أشهر، فاذا انقضى هذا الموعد دون الوفاء باالشتراكات السنوية زالت عضوية النقابة عنه بقوة القانون، وال
يجوز أن يعيد اسمه اال بإجراءات جديدة ورسوم قيد جديدة مع سداد رسوم االشتراكات المستحقة، وتضم المدة
السابقة على زوال عضويته من النقابة الى مدد القيد الجديدة.$ab170$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
