INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab179$تنعقد اللجنة بدعوة من رئيسها مرة كل ثالثين يوما على األقل ويجوز لها أن تدعو خبراء مختصين لالشتراك ف ي
اجتماعاتها دون أن يكون لهم حق التصويت .
