WITH ins_art_law17_183 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 183, $al183$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al183$, $ab183$تستحق الدمغة على المحام ي عند اثبات حضوره ألول مرة ف ي محاضر جلسات المحاكم أيا كان نوعها واللجان
القضائية واللجان االدارية ذات االختصاص القضائى وجلسات التحقيق الذي تجريه النيابات وجهات التحقيق
المختلفة .
وال يجوز للمحاكم والجهات المتقدمة أن تقبل حضور المحام ي أو تقبل تقديم أى دفاع أو أوراق منه اال إذا سدد
الدمغة. واذا تعدد المحامون ف ي الدعوى أو التحقيق ولو عن نفس الموكل، تعددت الدمغة.
وتكون قيمة طابع الدمغة ف ي الحاالت المتقدمة على النحو التال ى:
جنيه واحد عند الحضور أمام المحاكم الجزئية أو ف ي جلسات التحقيق.
جنيهان عند الحضور أمام المحاكم االبتدائية واالدارية.
ثالثة جنيهات عند الحضور أمام محاكم االستئناف والقضاء االدارى.
خمسة جنيهات عند الحضور أمام محاكم النقض واالدارية العليا والدستورية العليا. )٧ ($ab183$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
