المادة )٨٤( من هذا القانون فاذا قبل الطرفان نتيجة وساطتها، أستحقت الدمغة بواقع عشرة جنيهات من
الخمسمائة جنيه األولى من قيمة المتصالح عليه وعشرون جنيها عن الخمسمائة جنيه التالية وخمسون ج نيها عن
كل خمسمائة جنيه تالية ويلزم بسدادها المسئول عن قيمة المطالبة، ويتم لصقها على المحضر الذي تحرر اللجنة
ف ي هذا الشأن. واذا أصر أحد الطرفين على طلب النظر ف ي أمر التقدير ضوعف ما يستحق من دمغة على الطلب
وفق ما تقدم ويسددها مقدم الطلب ويرجع بها على المحكوم عليه.$ab184$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
