WITH ins_art_law17_187 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 187, $al187$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al187$, $ab187$على المحكمة من تلقاء نفسها وعند إصدار حكمها أن تلزم من خسر الدعوى بأتعاب المحاماة لصالح صندوق
الرعاية الصحية واالجتماعية بحيث ال تقل عن اآلت ى:
١ - خمسين جني ًها في الدعاوى المنظورة أمام المحاكم الجزئية .
٢ - خمسة وسبعين جني ًها في الدعاوى المنظورة أمام المحاكم االبتدائية واإلدارية.
٣ – مائة جنيه في الدعاوى المنظورة أمام محاكم االستئناف ومحاكم القضاء اإلدارى.
٤ – مائت ي جنيه في الدعاوى المنظورة أمام محاكم النقض واإلدارية العليا والدستورية العليا .
وتحصل أتعاب المحاماة مع الرسوم القضائية عند قيد الدعوى.
وعلى المحكمة في الدعوى الجنائية أن تحكم بأتعاب المحاماة الت ي يندب فيها محاٍم بحيث ال تقل عن اآلت ى:
١ - مائت ي جنيه في دعاوى الجنح المستأنفة.
٢ – ثالثمائة جنيه في دعاوى الجنايات .
٣ - خمسمائة جنيه في دعاوى النقض الجنائ ي .
ويحصل في قضايا التحكيم مبلغ خمسمائة جنيه كأتعاب محاماة تحصل مع الرسوم القضائية عند إيداع حكم
المحكمين بالمحكمة المختصة. )٨ ($ab187$
