WITH ins_art_law17_189 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 189, $al189$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al189$, $ab189$تودع أموال الصندوق ف ي حساب خاص بالمصروفات أو المصارف الت ي تختارها لجنة الصندوق ويكون
الصرف منها بناء على قرار من اللجنة وبتوقيع رئيسها أو أمين الصندوق أو من ينوب عنهما .
ويمسك الصندوق حسابات له مستقلة عن حسابات النقابة العامة.
ويكون للصندوق مراقب للحسابات تعينه الجمعية العمومية سنويا وتحدد أتعابه بناء على اقتراح مجلس النقابة.
ويجوز أن يكون مراقب حسابات النقابة مراقبا لحسابات الصندوق .$ab189$
  FROM laws WHERE law_no = 17 AND law_year = 1983
