INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab189$تودع أموال الصندوق ف ي حساب خاص بالمصروفات أو المصارف الت ي تختارها لجنة الصندوق ويكون
الصرف منها بناء على قرار من اللجنة وبتوقيع رئيسها أو أمين الصندوق أو من ينوب عنهما .
ويمسك الصندوق حسابات له مستقلة عن حسابات النقابة العامة.
ويكون للصندوق مراقب للحسابات تعينه الجمعية العمومية سنويا وتحدد أتعابه بناء على اقتراح مجلس النقابة.
ويجوز أن يكون مراقب حسابات النقابة مراقبا لحسابات الصندوق .$ab189$, '1983-03-31', 'active', NULL FROM ins_art_law17_189;

WITH ins_art_law17_190 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 190, $al190$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al190$, $ab190$تعفى أموال الصندوق الثابتة والمنقولة وجميع العمليات االستشارية مهما كان نوعها من الضرائب والرسوم
والدمغة والعوائد الت ي تفرضها الحكومة أو أى سلطة أخرى.
كما تعفى العمليات الت ي يباشرها الصندوق من الخضوع ألحكام القوانين الخاصة باإلشراف والرقابة على هيئات
التأمين. وذلك دون اخالل بحق مجلس النقابة ف ي أن يعهد الى الهيئة العامة للتأمين بندب بعض خبرائه
االكتواريين لفحص بعض أوجه نشاط الصندوق واستثماراته.$ab190$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
