WITH ins_art_law17_191 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 191, $al191$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al191$, $ab191$تعد اللجنة ف ي موعد ال يجاوز آخر فبراير من كل سنة مشروع موازنة السنة المقبلة والحساب الختام ي للسنة
المنتهية ويعرض على مجلس النقابة مع تقرير مراقب حسابات الصندوق للنظر فيه وعرضه على الجمعية
العمومية للصندوق. ويستمر العمل على أساس الموازنة السابقة حتى يتم اعتماده الموازنة الجديدة من الجمعية
العمومية .$ab191$
