WITH ins_art_law17_195 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 195, $al195$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al195$, $ab195$يفحص المركز المالى للصندوق مرة على األقل كل خمس سنوات بمعرفة خبير اكتواري تندبه الهيئة العامة
للتأمين بناء على طلب مجلس النقابة، فاذا تبين وجود عجز ف ي أموال الصندوق أوضح الخبير أسباب العجز وما
يقترحه من وسائل لتالفيه. ويعرض تقريره على مجلس النقابة ويبلغ الى لجنة الصندوق. ويكون على مجلس
النقابة ف ي هذه الحالة - بناء على المالحظات الت ي تبديها لجنة الصندوق - أن يدعو الجمعية العمومية لالنعقاد
ويعرض عليها ما يقترحه من وسائل لسد العجز. واذا تبين من نتيجة الفحص االكتواري وجود فائض ف ي
الصندوق، كان لمجلس النقابة أن يقترح على الجمعية العمومية اما زيادة االحتياط ي العام أو تكوين احتياطات
خاصة الغراض مختلفة أو زيادة المعاشات والخدمات الت ي يؤديها الصندوق للمنتفعين به.$ab195$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
