WITH ins_art_law17_196 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 196, $al196$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al196$, $ab196$للمحام ي الحق ف ي معاش كامل إذا توافرت فيه الشروط اآلتية :
١ - أن يكون اسمه مقيدا بجدول المحامين المشتغلين.
٢ - أن يكون قد مارس المحاماة ممارسة فعلية مدة خمس وعشرين سنة ميالدية متصلة أو منفصلة بما فيها مدة
التمرين الت ي ال تزيد على أربع سنوات مع احتساب مدة التجنيد اإللزامية الالحقة على القيد بالجدول ضمن المدد
السابقة، وذلك دون اإلخالل بحكم المادة )٢٤( من هذا القانون. )٨ (
٣ - أن يكون قد بلغ ستين سنة ميالدية على األقل.
ويعتبر ف ي حكم بلوغ سن الستين وفاة المحام ي أو عجزه عجزا كامال مستديما .
٤ - أن يكون مسددا لرسوم االشتراك المستحق عليه ما لم يكن قد أعفى منها طبقا ألحكام هذا القانون.$ab196$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
