١٠١ لسنة ١٩٤٤ طبقا لآلت ي:
١ - خمسون ف ي المائة من المعاش الذي لم يكن يجاوز أربعين جنيها.
٢ - أربعون ف ي المائة من المعاش الذي لم يكن يجاوز خمسين جنيها .
٣ - ثالثون ف ي المائة من المعاش الذي لم يكن يجاوز ستين جنيها .
٤ - عشرون ف ي المائة من المعاش ف ي الحاالت األخرى .
ويكون الحد األدنى لنصيب المستحقين عن صاحب المعاش خمسة وثالثين جنيها ف ي الشهر بالنسبة لالرملة
