INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
SELECT id, 1, $ab213$إذا طرأ على المحام ي ما يقتض ي معاونته ماليا جاز للجنة الصندوق أن تقرر له معونة وقتية لمواجهة حالتة أو
معونة شهرية ثابته لمدة ال تجاوز سنة .
وللجنة أن تقرر معونة للمستحقين عن المتوفى طبقا ألحكام هذا القانون إذا لم تتوفر له شروط الحصول على
معاش التقاعد.
وفى جميع األحوال ال يجوز أن يزيد مجموع ما يحصل عليه المحام ي أو المستحقون عنه من معونات عن الحد
األقصى لمعاش سنة واحدة .$ab213$, '1983-03-31', 'active', NULL FROM ins_art_law17_213;

WITH ins_art_law17_214 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 214, $al214$الباب الرابع — صندوق الرعاية االجتماعية والصحي ة$al214$, $ab214$يكفل الصندوق، الرعاية الصحية للمحامين المقيدين بالجدول العام وأسرهم طبقا للقواعد الموحدة الت ي تقررها
الالئحة التنفيذية للرعاية االجتماعية والصحية على أن يتم توفير الرعاية الصحية على مستوى النقابات الفرعية
وطبقا لالعتمادات السنوية الت ي تخصص لكل منها الموازنة التقديرية .
ويجوز أن يكون ذلك عن طريق انشاء نظام للتأمين الصح ي.$ab214$
  FROM laws WHERE law_no = 17 AND law_year = 1983
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
