عض ًوا يختارهم مجلس النقابة العامة، ويجوز أن يتعين في مجلس اإلدارة أربعة أعضاء على األكثر من أعضاء
مجلس النقابة العامة .
ويضع مجلس النقابة العامة جميع اللوائح اإلدارية والمالية والفنية المنظمة لألكاديمية، ويحدد هيكلها الفن ي
واإلداري وضوابط القبول والدراسة ومدتها ومناهجها واستصدار المعادالت للمؤهالت المهنية الصادرة عنها .
